/** Isolated W3 diagnostic only; reads counters without running the classifier. */
fun diagnosticSnapshot(): Map<String, Int> {
    val hasSpeech = speechSamples >= 4096
    val start = if (hasSpeech) maxOf(0, firstSpeech - 3200) else -1
    val end = if (hasSpeech) minOf(size, lastSpeech + 3200) else -1
    return linkedMapOf(
        "consumedSamples" to size,
        "firstSpeechSample" to firstSpeech,
        "lastSpeechEndSample" to lastSpeech,
        "speechSamples" to speechSamples,
        "preparedStartSample" to start,
        "preparedEndSample" to end,
        "preparedSamples" to if (hasSpeech) end - start else 0
    )
}

